@using sv_06a8e0525e544ae49cf78000a7d6d534.Services

<div class="message-area">
    <div class="message-area-header">
        <h4># @Channel.Name</h4>
        <span class="channel-desc">@Channel.Description</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ReplyCount="GetReplyCount(message.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="OnReact" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-textarea"
                  @bind="newMessageText"
                  @bind:event="oninput"
                  placeholder="Message #@Channel.Name"
                  @onkeydown="HandleKeyDown"></textarea>
        <button class="btn-send" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageText)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private string newMessageText = string.Empty;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;
        var text = newMessageText;
        newMessageText = string.Empty;
        await OnSendMessage.InvokeAsync(text);
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers load more (JS interop would be ideal for precise detection)
        await OnLoadMore.InvokeAsync();
    }
}

